def transform(grid):
    h, w = len(grid), len(grid[0])

    def bands(length, occupied):
        result = []
        i = 0
        while i < length:
            if not occupied(i):
                i += 1
                continue
            start = i
            while i + 1 < length and occupied(i + 1):
                i += 1
            result.append((start, i))
            i += 1
        return result

    rb = bands(h, lambda r: any(v != 0 for v in grid[r]))
    cb = bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))
    out = [row[:] for row in grid]

    # In each tile, its most common nonzero color is the scaffold;
    # other nonzero cells are the marked pattern.
    marks = {}
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            cells = [grid[r][c] for r in range(r0, r1 + 1)
                     for c in range(c0, c1 + 1) if grid[r][c] != 0]
            if not cells:
                continue
            scaffold = max(set(cells), key=cells.count)
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    color = grid[r][c]
                    if color and color != scaffold:
                        marks[(ri, ci, r - r0, c - c0)] = color

    # Join matching marked cells through the blank separators between tiles.
    for ri, (r0, r1) in enumerate(rb):
        max_local_r = r1 - r0
        max_local_c = max((c1 - c0 for c0, c1 in cb), default=-1)
        for dr in range(max_local_r + 1):
            for dc in range(max_local_c + 1):
                by_color = {}
                for ci, (c0, c1) in enumerate(cb):
                    color = marks.get((ri, ci, dr, dc))
                    if color is not None:
                        by_color.setdefault(color, []).append((c0, c1))
                for color, spans in by_color.items():
                    for (_, left_end), (right_start, _) in zip(spans, spans[1:]):
                        for c in range(left_end + 1, right_start):
                            r = r0 + dr
