def transform(grid):
    from collections import Counter

    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return out

    base = counts.most_common(1)[0][0]
    other_counts = Counter(v for row in grid for v in row if v not in (0, base))
    if not other_counts:
        return out

    # The most common non-background interior color is the repeated,
    # unmarked pattern; connect the remaining colors.
    ordinary = other_counts.most_common(1)[0][0]
    h, w = len(grid), len(grid[0])

    for color in other_counts:
        if color == ordinary:
            continue

        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == 0:
                        out[r][c] = color

        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(rows, rows[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] == 0:
                        out[r][c] = color

    return out
